using Aurora.Core;
using Aurora.Editor;
static class SharedTransportMaterialChecks
{
 public static async Task Run(Action<bool,string> check,Action<Action,string> reject,string? native)
 {
  var model=ObjImporter.Parse("o body\nv 0 0 0\nv 1 0 0\nv 0 1 0\nusemtl exported_alias\nf 1 2 3\n").Model;var original=model.Data.ToArray();var aligned=ModelEditing.NativeMaterialSlots(model,["body_paint","trailer_paint"]);check(aligned.Materials.SequenceEqual(new[]{"body_paint"})&&model.Data.SequenceEqual(original)&&aligned.Nodes[0].Positions.SequenceEqual(model.Nodes[0].Positions),"native slot canonicalization preserves geometry and source when MTL also contains trailer materials");var conflicting=ModelEditing.AddMaterial(ModelEditing.MaterialSlots(model,["B"]),"unknown");reject(()=>ModelEditing.NativeMaterialSlots(conflicting,["A","B","C"]),"partial shared-material mapping with conflicting indices rejected");
  string root=Path.Combine(Path.GetTempPath(),"Aurora-shared-materials-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  try{
   string pbr=Path.Combine(root,"alias.pbr");File.WriteAllText(pbr,"{material exported_alias\n {roughness_factor = 0.3}\n}\n{material trailer_paint\n {metallic_factor = 0.8}\n}\n");var settings=MaterialDocuments.Pbr(pbr,new Dictionary<string,MaterialSettings>{{"body_paint",new()},{"trailer_paint",new()}},new Dictionary<string,string>{{"exported_alias","body_paint"}});check(settings.Count==2&&settings["body_paint"].Roughness==.3f&&settings["trailer_paint"].Metallic==.8f,"PBR alias follows canonical root material without replacing trailer material");
   byte[] opaque=model.Data.ToArray();int nodeOffset=20+model.Materials.Length*64;BitConverter.GetBytes(1).CopyTo(opaque,nodeOffset);string linked=Path.Combine(root,"part.nmf");File.WriteAllBytes(linked,opaque);string remapped=VehicleSharedMaterials.Export("$JOINT part.nmf 0 0 // keep\n$PROPELER_LOW 1 part.nmf own.mtl\n$END\n$JOINT ignored.nmf 0 0\n",root,["body_paint","trailer_paint"]);string relative=VehicleScript.Tokens(remapped).First(t=>t.Key=="JOINT"&&t.Index==0).Value;var rewritten=File.ReadAllBytes(Path.Combine(root,relative));check(NativeModel.ReadMaterialNames(rewritten).SequenceEqual(new[]{"body_paint"})&&rewritten.AsSpan(nodeOffset).SequenceEqual(opaque.AsSpan(nodeOffset))&&File.ReadAllBytes(linked).SequenceEqual(opaque)&&remapped.Contains("$PROPELER_LOW 1 part.nmf own.mtl")&&remapped.Contains("// keep")&&remapped.Contains("$JOINT ignored.nmf"),"shared table remapping preserves opaque nodes, original assets, independent part material and terminator");
   if(native==null||VehicleAssets.Media(native) is not string media)return;int verified=0,aliases=0,missing=0;
