    var canonical=ModelEditing.NativeMaterialSlots(primary,NativeMaterialText.Names(File.ReadAllText(material)));var maps=MaterialDocuments.Native(material,canonical);if(!ReferenceEquals(canonical,primary))aliases++;part=ModelEditing.NativeMaterialSlots(part,NativeMaterialText.Names(File.ReadAllText(material)));if(part.Nodes.SelectMany(n=>n.Groups).Any(g=>!maps.ContainsKey(part.Materials[g.Material]))){missing++;continue;}verified++;
    if(Path.GetFileName(Path.GetDirectoryName(file))!="bust_skd_9Tr_po1e")continue;
    string folder=Path.Combine(root,"export");Directory.CreateDirectory(folder);var models=new Dictionary<string,NativeModel>{{Path.Combine(Path.GetDirectoryName(file)!,"main.nmf"),canonical}};foreach(var lod in VehicleScript.Tokens(script).Where(t=>System.Text.RegularExpressions.Regex.IsMatch(t.Key,@"^LOD\d*$")&&t.Index==0)){string lodPath=VehicleAssets.Resolve(lod.Value,Path.GetDirectoryName(file)!,media);models[lodPath]=ModelEditing.NativeMaterialSlots(new(File.ReadAllBytes(lodPath)),NativeMaterialText.Names(File.ReadAllText(material)));}await ModelExport.Export(models,models.Keys.ToDictionary(p=>p,_=>new HashSet<string>()),maps,material,null,null,folder,p=>Task.FromResult(DdsImage.Decode(File.ReadAllBytes(p))),script,useSourceScript:false);string exported=Directory.GetDirectories(folder).Single();var exportedNames=NativeMaterialText.Names(File.ReadAllText(Path.Combine(exported,"material.mtl")));var exportedModel=new NativeModel(File.ReadAllBytes(Path.Combine(exported,"main.nmf")));var token=VehicleScript.Tokens(File.ReadAllText(Path.Combine(exported,"script.ini"))).First(t=>t.Key=="JOINT"&&t.Index==0);var exportedJoint=new NativeModel(File.ReadAllBytes(Path.Combine(exported,token.Value)));check(exportedModel.Materials.Concat(exportedJoint.Materials).All(exportedNames.Contains)&&exportedNames.Contains("MTZ")&&exportedNames.Contains("PO1"),"native Skoda with root material alias exports root, joint and all three shared materials");
   }check(verified>40,"shared native MTL covers main and joint material tables: "+verified+"; normalized root aliases: "+aliases+"; native missing joint materials: "+missing);
  }finally{Directory.Delete(root,true);}
 }
}
